namespace Application.Ingestion;

public sealed record StoredBlob(string Key, string Sha256Hex, long Length);

/// <summary>Stores uploaded files. Keys are generated by the store, never derived from user input.</summary>
public interface IBlobStorage
{
    Task<StoredBlob> SaveAsync(Guid tenantId, Guid workspaceId, Stream content, CancellationToken cancellationToken);

    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken);

    /// <summary>Idempotent: deleting a missing blob is not an error.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}

/// <summary>Turns a stored file into plain text. Throws <see cref="IngestionException"/> for unreadable files.</summary>
public interface IDocumentTextExtractor
{
    Task<string> ExtractAsync(DocumentFormat format, Stream content, CancellationToken cancellationToken);
}

/// <summary>Produces one embedding per text. All vectors have <c>Domain.DocumentChunk.EmbeddingDimensions</c> entries.</summary>
public interface IEmbeddingClient
{
    Task<IReadOnlyList<float[]>> EmbedAsync(IReadOnlyList<string> texts, CancellationToken cancellationToken);
}

/// <summary>Cross-instance mutual exclusion (Redis in production).</summary>
public interface IDistributedLock
{
    /// <summary>Returns a handle that releases the lock when disposed, or null if someone else holds it.</summary>
    Task<IAsyncDisposable?> TryAcquireAsync(string key, TimeSpan ttl, CancellationToken cancellationToken);
}

public sealed record DocumentStatusChanged(
    Guid TenantId, Guid WorkspaceId, Guid DocumentId, string Status, int ChunkCount, string? FailureReason);

/// <summary>Pushes ingestion progress to interested clients (SignalR). Delivery is best-effort.</summary>
public interface IIngestionNotifier
{
    Task DocumentStatusChangedAsync(DocumentStatusChanged change, CancellationToken cancellationToken);
}

/// <summary>
/// A failure during ingestion. <see cref="IsPermanent"/> failures (corrupt, empty or unsupported content)
/// will never succeed on retry, so they fail the document immediately instead of burning retries.
/// </summary>
public sealed class IngestionException : Exception
{
    public IngestionException()
    {
    }

    public IngestionException(string message)
        : base(message)
    {
    }

    public IngestionException(string message, Exception innerException)
        : base(message, innerException)
    {
    }

    public bool IsPermanent { get; private init; }

    public static IngestionException Permanent(string message, Exception? inner = null) =>
        inner is null
            ? new IngestionException(message) { IsPermanent = true }
            : new IngestionException(message, inner) { IsPermanent = true };
}
